#include <iostream>
template <typename T>
class Z {
public:
  void f() { std::cout << "Z<T>::f() called\n"; }
  void g() { std::cout << "Z<T>::g() called\n"; }
};
template <typename T>
T z_var = T();
int main() {
  Z<int> a; a.f();
  Z<char>* p = new Z<char>(); p->g(); delete p;
  // Z<double> instantiation is NOT required here.
  std::cout << z_var<int> << std::endl; //Instantiates z_var<int>
  return 0;
}
